INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (1, 1, 1, 'Hồ Chí Minh – Đà Nẵng – Bán đảo Sơn Trà', 'Đón khách tại sân bay Đà Nẵng, tham quan chùa Linh Ứng Sơn Trà, tắm biển Mỹ Khê buổi chiều.', 'Trưa, Tối', 'Khách sạn 4* Đà Nẵng');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (2, 1, 2, 'Bà Nà Hills – Cầu Vàng', 'Đi cáp treo lên Bà Nà, check-in Cầu Vàng, vui chơi Fantasy Park.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Đà Nẵng');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (3, 1, 3, 'Phố cổ Hội An', 'Tham quan chùa Cầu, nhà cổ Tấn Ký, thả đèn hoa đăng trên sông Hoài.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Đà Nẵng');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (4, 1, 4, 'Đà Nẵng – Hồ Chí Minh', 'Tự do mua sắm chợ Hàn, xe đưa ra sân bay về lại Hồ Chí Minh.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (5, 2, 1, 'Hà Nội – Phú Quốc', 'Đón khách tại sân bay Phú Quốc, nhận phòng resort, ngắm hoàng hôn Sunset Town.', 'Tối', 'Resort 5* Phú Quốc');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (6, 2, 2, 'Tour 4 đảo bằng cano', 'Khám phá Hòn Móng Tay, Hòn Gầm Ghì, lặn ngắm san hô, ăn trưa trên đảo.', 'Sáng, Trưa', 'Resort 5* Phú Quốc');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (7, 2, 3, 'Chợ Dương Đông – Về Hà Nội', 'Mua đặc sản nước mắm, ngọc trai, xe đưa ra sân bay.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (8, 3, 1, 'Hà Nội – Nha Trang', 'Đến Cam Ranh, nhận phòng, dạo biển Trần Phú buổi tối.', 'Tối', 'Khách sạn 4* Nha Trang');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (9, 3, 2, 'Đảo Hòn Mun – Lặn biển', 'Ngắm san hô tại khu bảo tồn biển Hòn Mun, tắm bùn khoáng buổi chiều.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Nha Trang');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (10, 3, 3, 'Tháp Bà Ponagar – Tự do', 'Tham quan tháp Chăm cổ, buổi chiều tự do vui chơi VinWonders.', 'Sáng, Trưa', 'Khách sạn 4* Nha Trang');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (11, 3, 4, 'Nha Trang – Hà Nội', 'Mua sắm chợ Đầm, ra sân bay Cam Ranh.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (12, 4, 1, 'Hà Nội – Đà Lạt', 'Đến Liên Khương, dạo hồ Xuân Hương, chợ đêm Đà Lạt.', 'Tối', 'Khách sạn 3* Đà Lạt');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (13, 4, 2, 'Thung lũng Tình Yêu – Đồi chè Cầu Đất', 'Săn mây đồi chè sáng sớm, tham quan vườn dâu, thiền viện Trúc Lâm.', 'Sáng, Trưa, Tối', 'Khách sạn 3* Đà Lạt');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (14, 4, 3, 'Đà Lạt – Hà Nội', 'Ga Đà Lạt cổ, mua mứt, atiso làm quà, ra sân bay.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (15, 5, 1, 'Hồ Chí Minh – Hà Nội', 'Đến Nội Bài, tham quan Hồ Gươm, phố cổ, xem múa rối nước.', 'Trưa, Tối', 'Khách sạn 4* Hà Nội');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (16, 5, 2, 'Vịnh Hạ Long', 'Lên du thuyền, tham quan hang Sửng Sốt, chèo kayak, nghỉ đêm trên vịnh.', 'Sáng, Trưa, Tối', 'Du thuyền 4* Hạ Long');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (17, 5, 3, 'Hạ Long – Sapa', 'Ngắm bình minh trên vịnh, di chuyển lên Sapa bằng xe limousine.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Sapa');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (18, 5, 4, 'Bản Cát Cát – Fansipan', 'Khám phá bản Cát Cát, tự chọn cáp treo chinh phục Fansipan.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Sapa');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (19, 5, 5, 'Sapa – Hà Nội – Hồ Chí Minh', 'Về Hà Nội, ra sân bay Nội Bài.', 'Sáng, Trưa', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (20, 6, 1, 'Hồ Chí Minh – Singapore', 'Đến Changi, tham quan Jewel, công viên Merlion, Marina Bay về đêm.', 'Tối', 'Khách sạn 4* Singapore');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (21, 6, 2, 'Gardens by the Bay', 'Tham quan Flower Dome, Cloud Forest, xem show ánh sáng Supertree.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Singapore');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (22, 6, 3, 'Đảo Sentosa', 'Tự do vui chơi Sentosa, Universal Studios (tự túc vé).', 'Sáng, Tối', 'Khách sạn 4* Singapore');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (23, 6, 4, 'Singapore – Hồ Chí Minh', 'Mua sắm Orchard Road, ra sân bay.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (24, 7, 1, 'Hồ Chí Minh – Bangkok', 'Đến Suvarnabhumi, tham quan chùa Phật Vàng, du thuyền sông Chao Phraya.', 'Tối', 'Khách sạn 4* Bangkok');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (25, 7, 2, 'Bangkok – Pattaya', 'Di chuyển Pattaya, xem show Alcazar, phố đi bộ Walking Street.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Pattaya');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (26, 7, 3, 'Đảo Coral', 'Đi cano ra đảo Coral, tắm biển, các trò chơi trên biển.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Pattaya');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (27, 7, 4, 'Pattaya – Bangkok', 'Về Bangkok, tham quan Hoàng cung, mua sắm Platinum.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Bangkok');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (28, 7, 5, 'Bangkok – Hồ Chí Minh', 'Tự do, ra sân bay.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (29, 8, 1, 'Hà Nội – Seoul', 'Bay đêm đến Incheon.', NULL, NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (30, 8, 2, 'Đảo Nami – Petite France', 'Tham quan đảo Nami, làng Pháp, nhận phòng tại Seoul.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Seoul');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (31, 8, 3, 'Công viên Everland', 'Vui chơi cả ngày tại Everland.', 'Sáng, Tối', 'Khách sạn 4* Seoul');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (32, 8, 4, 'Cung Gyeongbok – Myeongdong', 'Mặc hanbok tham quan cung điện, mua sắm Myeongdong.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Seoul');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (33, 8, 5, 'Seoul – Hà Nội', 'Ghé cửa hàng sâm, mỹ phẩm, ra sân bay.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (34, 9, 1, 'Hồ Chí Minh – Huế', 'Đến Phú Bài, tham quan Đại Nội, đi thuyền rồng nghe ca Huế.', 'Trưa, Tối', 'Khách sạn 3* Huế');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (35, 9, 2, 'Lăng tẩm – Chùa Thiên Mụ', 'Tham quan lăng Khải Định, lăng Tự Đức, chùa Thiên Mụ.', 'Sáng, Trưa, Tối', 'Khách sạn 3* Huế');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (36, 9, 3, 'Huế – Hồ Chí Minh', 'Chợ Đông Ba, ra sân bay.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (37, 10, 1, 'Hồ Chí Minh – Tokyo', 'Bay đêm đến Narita, tham quan chùa Asakusa, tháp Tokyo Skytree.', 'Trưa, Tối', 'Khách sạn 4* Tokyo');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (38, 10, 2, 'Núi Phú Sĩ', 'Tham quan trạm 5 núi Phú Sĩ, làng cổ Oshino Hakkai, tắm onsen.', 'Sáng, Trưa, Tối', 'Khách sạn onsen');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (39, 10, 3, 'Shinkansen – Kyoto', 'Đi tàu cao tốc đến Kyoto, tham quan chùa Vàng Kinkakuji.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Kyoto');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (40, 10, 4, 'Kyoto – Osaka', 'Đền Fushimi Inari, lâu đài Osaka.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Osaka');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (41, 10, 5, 'Osaka – Tokyo', 'Về Tokyo, mua sắm Ginza, Shinjuku.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Tokyo');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (42, 10, 6, 'Tokyo – Hồ Chí Minh', 'Ra sân bay Narita.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (43, 11, 1, 'Hồ Chí Minh – Hồng Kông', 'Đến sân bay, đi cáp treo Ngong Ping, tượng Phật Thiên Đàn.', 'Trưa, Tối', 'Khách sạn 4* Hồng Kông');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (44, 11, 2, 'Disneyland', 'Vui chơi cả ngày tại Hong Kong Disneyland.', 'Sáng', 'Khách sạn 4* Hồng Kông');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (45, 11, 3, 'Đỉnh Victoria – Đại lộ Ngôi sao', 'Đi tàu điện lên đỉnh Victoria, ngắm cảng Victoria về đêm.', 'Sáng, Trưa, Tối', 'Khách sạn 4* Hồng Kông');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (46, 11, 4, 'Hồng Kông – Hồ Chí Minh', 'Tự do mua sắm, ra sân bay.', 'Sáng', NULL);
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (47, 12, 1, 'Hồ Chí Minh – Phú Quốc', 'Đến Phú Quốc, nhận phòng resort, tự do tắm biển.', NULL, 'Resort 4* Phú Quốc');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (48, 12, 2, 'Nam đảo Phú Quốc', 'Tự túc tham quan bãi Sao, nhà tù Phú Quốc.', 'Sáng', 'Resort 4* Phú Quốc');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (49, 12, 3, 'Tự do nghỉ dưỡng', 'Nghỉ dưỡng tại resort, spa (tự túc).', 'Sáng', 'Resort 4* Phú Quốc');
INSERT INTO tour_itineraries (id, tour_id, day_no, title, description, meals, hotel) VALUES (50, 12, 4, 'Phú Quốc – Hồ Chí Minh', 'Trả phòng, ra sân bay.', 'Sáng', NULL);
